CREATE COLUMN TABLE "TEST_AP"."OTSP" ("AbsEntry" INTEGER CS_INT NOT NULL , "TransCode" NVARCHAR(20) NOT NULL , "TransName" NVARCHAR(25), "TransID" NVARCHAR(15), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "DataSource" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTSP_TRANS_CODE" ON "TEST_AP"."OTSP" ( "TransCode" ASC )